import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
import "../styles/navbar.css"; // Ensure this is correctly imported

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem("token"));
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState(""); 

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      const owner = JSON.parse(ownerData);
      setAvatar(owner.avatar || "default-avatar.png"); // Set avatar or default
    }

    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("");
    window.location.reload();
  };

  const handleAvatarClick = () => {
    setDropdownVisible((prev) => !prev);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  return (
    <nav id="menu" className="navbar-custom">
      <div className="container">
        <div className="navbar-header">
          <button type="button" className="navbar-toggle collapsed">
            <span className="sr-only">Toggle navigation</span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
          </button>
          <a className="navbar-brand page-scroll" href="#page-top">
            <img src={require("../assets/Logo.png")} alt="Petopia Logo" className="logo" />
          </a>
        </div>

        <div className="collapse navbar-collapse">
          <ul className="nav navbar-nav navbar-right">
            {!isLoggedIn && (
              <>
                <li>
                  <a href="/#header" className="nav-link">Home</a>
                </li>
                <li>
                  <Link to="/login" className="nav-link">Log In</Link>
                </li>
              </>
            )}

            {isLoggedIn && (
              <li className="nav-profile" ref={dropdownRef}>
                <img
                  src={avatar}
                  alt="Profile"
                  className="avatar"
                  onClick={handleAvatarClick}
                />
                {dropdownVisible && (
                  <div className="dropdown-menu-custom">
                    <div className="dropdown-item" onClick={handleProfileClick}>Profile</div>
                    <div className="dropdown-item" onClick={handleLogout}>Logout</div>
                  </div>
                )}
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
